#!/bin/sh
# build.sh : R6a-base -> P1 (rules/planes/EP) -> P2 (hand power) -> P3 (A* SW/SPK) -> P4 (A* SYS/BAT branches) -> P5 (A* rails) -> P6 (widen) -> P7 (final, locked)
W=/home/chithi/Desktop/DesktopSpeaker/ai-files/pcb/work-r6; H=/home/chithi/Desktop/DesktopSpeaker/ai-files/helpers
FP="flatpak run --filesystem=/home/chithi/Desktop/DesktopSpeaker --command=python3 org.kicad.KiCad"
cd $W
$FP $H/route_r6a_phase1.py R6a-base.kicad_pcb P1.kicad_pcb 2>&1 | grep -v Gtk | cut -c1-300
$FP $H/route_r6a_power.py P1.kicad_pcb P2.kicad_pcb 2>&1 | grep -v Gtk | cut -c1-400
$FP $H/route_r6a_astar.py P2.kicad_pcb P3.kicad_pcb "Net-(U6-OUT_A-),Net-(U6-OUT_B-),Net-(U7-OUT_A+),Net-(U7-OUT_B+),Net-(U14-L1),Net-(U14-L2),Net-(U15-L1),Net-(U15-L2),Net-(C302-Pad1),Net-(C303-Pad1),Net-(C304-Pad1),Net-(C305-Pad1),Net-(C306-Pad1),Net-(C307-Pad1)" 2>&1 | grep -v Gtk | grep -v " OK "
$FP $H/route_r6a_astar.py P3.kicad_pcb P4.kicad_pcb "SYS_RAW,BAT_PACK" --prm '{"/SYS_RAW":{"layers":[0,1,2],"viacost":3,"inner_pref":1,"tiers":[2.0,1.5,1.0,0.5],"maxexp":90000000,"margins":[10,30]},"/Fuel_Gauge_Power/BAT_PACK":{"layers":[0,1,2],"viacost":3,"inner_pref":1}}' 2>&1 | grep -v Gtk | grep -v " OK "
P='{"/Battery_Charger/REGN":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.0,0.8,0.5,0.4]},"/Fuel_Gauge_Power/USB_AUX_5V":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.0,0.8,0.5,0.4]},"/5V_LOGIC":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[2.0,1.5,1.0,0.4],"maxexp":90000000,"margins":[10,30]},"/5V_CODEC":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.5,1.0,0.8,0.4],"margins":[10,30]},"/3V8_BT":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.5,1.0,0.8,0.3]},"/3V_AO":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.0,0.8,0.5,0.3],"maxexp":250000000,"margins":[15,45]},"/3V3_AUDIO":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.5,1.0,0.8,0.3],"maxexp":90000000,"margins":[10,30]},"/USB_PD/LDO_3V3":{"layers":[0,1,2],"inner_pref":1,"viacost":3,"tiers":[1.0,0.8,0.5,0.3],"margins":[10,30]}}'
$FP $H/route_r6a_astar.py P4.kicad_pcb P5.kicad_pcb "REGN,USB_AUX_5V,5V_LOGIC,5V_CODEC,3V8_BT,3V_AO,3V3_AUDIO,LDO_3V3,LDO_1V5,Net-(U1-SYS_PWR),Net-(U1-VDD_IO)" --prm "$P" --seeds "139.8,70.0" 2>&1 | grep -v Gtk | grep -v " OK "
$FP $H/route_r6a_astar.py P5.kicad_pcb P5b.kicad_pcb "3V_AO,3V3_AUDIO,5V_LOGIC,5V_CODEC,REGN,3V8_BT,USB_AUX_5V,LDO_3V3" --prm '{"/3V_AO":{"layers":[0,1,2],"viacost":4,"tiers":[0.8,0.5,0.3,0.2],"maxexp":250000000,"margins":[6,15]},"/3V3_AUDIO":{"layers":[0,1,2],"viacost":4,"tiers":[0.8,0.5,0.3,0.2],"maxexp":250000000,"margins":[6,15,30]}}' --seeds "139.8,70.0" 2>&1 | grep -v Gtk | grep -v " OK "
$FP $H/route_r6a_astar.py P5b.kicad_pcb P5c.kicad_pcb "/USB_PD/VIN_LOW,Net-(U10-CPN),Net-(U10-CPP),Net-(U10-HPVDD),Net-(U10-HPVSS),Net-(U2-VBUS),Net-(U2-VCCCI),Net-(U2-VCCP1I),Net-(U2-VCCP2I),Net-(U2-VCCXI),Net-(U24-AVDD),Net-(U24-LDO),Net-(U25-VCC),Net-(U6-AVDD),Net-(U6-GVDD),Net-(U6-VR_DIG),Net-(U7-AVDD),Net-(U7-GVDD),Net-(U7-VR_DIG)" --prm "$(python3 -c 'import json;print(json.dumps({n:{"layers":[0],"vias":False,"viacost":0,"tiers":[0.5,0.4,0.3,0.2],"floor":0.2,"cme":0.2} for n in "/USB_PD/VIN_LOW,Net-(U10-CPN),Net-(U10-CPP),Net-(U10-HPVDD),Net-(U10-HPVSS),Net-(U2-VBUS),Net-(U2-VCCCI),Net-(U2-VCCP1I),Net-(U2-VCCP2I),Net-(U2-VCCXI),Net-(U24-AVDD),Net-(U24-LDO),Net-(U25-VCC),Net-(U6-AVDD),Net-(U6-GVDD),Net-(U6-VR_DIG),Net-(U7-AVDD),Net-(U7-GVDD),Net-(U7-VR_DIG)".split(",")}))')" 2>&1 | grep -v Gtk | grep -v " OK " | grep -v "^  FAIL"
$FP $H/route_r6a_widen.py P5c.kicad_pcb P6.kicad_pcb 2>&1 | grep -v Gtk
$FP $H/route_r6a_final.py P6.kicad_pcb P7.kicad_pcb 2>&1 | grep -v Gtk
$FP $H/route_r6a_dogbone.py P7.kicad_pcb P8.kicad_pcb 2>&1 | grep -v "Gtk\|Debug"
$FP $H/route_r6a_u14fix.py P8.kicad_pcb P9.kicad_pcb 2>&1 | grep -v "Gtk\|Debug"
$FP $H/route_r6a_swwiden.py P9.kicad_pcb P10.kicad_pcb 2>&1 | grep -v "Gtk\|Debug"
for e in kicad_pcb; do cp P10.$e R6a-final.$e; done; cp R6a.kicad_pro R6a-final.kicad_pro; cp R6a.kicad_dru R6a-final.kicad_dru
